import{_ as a,o as s,c as i,a2 as n}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"四种引用类型","description":"","frontmatter":{},"headers":[],"relativePath":"language/java/four-references.md","filePath":"language/java/four-references.md","lastUpdated":1781086744000}'),t={name:"language/java/four-references.md"};function r(p,e,o,l,h,c){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="四种引用类型" tabindex="-1">四种引用类型 <a class="header-anchor" href="#四种引用类型" aria-label="Permalink to &quot;四种引用类型&quot;">​</a></h1><p>在 Java 语言中，除了基本数据类型外，其他的都是指向各类的对象引用；Java 中根据其生命周期的长短，将引用分为 4 类：强引用，软引用，弱引用，幻象引用（虚引用）。</p><h2 id="强引用" tabindex="-1">强引用 <a class="header-anchor" href="#强引用" aria-label="Permalink to &quot;强引用&quot;">​</a></h2><p>我们平时编码 <code>Object obj = new Object()</code> 中的 <code>obj</code> 就是强引用。通过关键字 new 创建的对象所关联的引用就是强引用。</p><p>当 JVM 内存空间不足，JVM 宁愿抛出 OutOfMemoryError 运行时错误（OOM），使程序异常终止，也不会靠随意回收具有强引用的“存活”对象来解决内存不足的问题。</p><p>对于一个普通的对象，如果没有其他的引用关系，只要超过了引用的作用域或者显示地将相应（强）引用赋值为 null，就是可以被垃圾回收的了，而其具体垃圾回收时机还需要看垃圾回收策略。</p><h2 id="软引用" tabindex="-1">软引用 <a class="header-anchor" href="#软引用" aria-label="Permalink to &quot;软引用&quot;">​</a></h2><p>软引用通过 <code>SoftReference</code> 类实现。软引用的生命周期比强引用短一些。</p><p>只有当 JVM 认为内存不足时，才会去试图回收软引用指向的对象：即 JVM 会确保在抛出 OutOfMemoryError 之前，清理软引用指向的对象。</p><p>软引用可以和一个引用队列（ReferenceQueue）联合使用，如果软引用所指向的对象被垃圾回收器回收，Java 虚拟机就会把这个软引用加入到与之关联的引用队列中。 后续，我们可以通过调用 <code>ReferenceQueue</code> 中的 <code>poll()</code> 方法来检查是否有它关心的对象被回收。如果队列为空，将返回一个 null，否则该方法返回队列中前面的一个 Reference 对象。</p><p>应用场景：软引用通常用来实现内存敏感的缓存。如果还有内存空闲，就可以暂时保留缓存；当内存不足时清理掉。这里就保证了使用缓存的同时，不会耗尽内存。</p><h2 id="弱引用" tabindex="-1">弱引用 <a class="header-anchor" href="#弱引用" aria-label="Permalink to &quot;弱引用&quot;">​</a></h2><p>弱引用通过 <code>WeakReference</code> 类实现。弱引用的生命周期比软引用更短。</p><p>在垃圾回收器扫描它所管理的内存区域的过程中，一旦发现了具有弱引用的对象，不管当前内存空间是否足够，都会回收它的内存。</p><p>由于垃圾回收器是一个优先级很低的线程，因此不一定会很快回收弱引用的对象。</p><p>弱引用可以和一个引用队列（ReferenceQueue）联合使用，如果弱引用所指向的对象被垃圾回收器回收，Java 虚拟机就会把这个弱引用加入到与之关联的引用队列中。</p><p>应用场景：弱引用同样可以应用在内存敏感的缓存中。</p><h2 id="幻象引用-虚引用" tabindex="-1">幻象引用（虚引用） <a class="header-anchor" href="#幻象引用-虚引用" aria-label="Permalink to &quot;幻象引用（虚引用）&quot;">​</a></h2><p>幻象引用也叫虚引用，通过 <code>PhantomReference</code> 类来实现。</p><p>我们无法通过虚引用访问对象的任何属性和方法。虚引用仅仅提供了一种确保对象被 finalize 之后，做某些事的机制。</p><p>如果一个对象仅持有虚引用，那么它和没有任何引用一样，在任何时候都可能会垃圾回收器回收。</p><p>虚引用必须和引用队列（ReferenceQueue）联合使用。当垃圾回收器准备回收一个对象时，如果发现它还有虚引用，就会在回收对象的内存之前，把这个虚引用加入到与之关联的引用队列中。</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ReferenceQueue queue </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ReferenceQueue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PhantomReference pr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PhantomReference</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(object, queue);</span></span></code></pre></div><p>程序可以通过判断引用队列中是否已经加入了虚引用，来了解被引用对象是否将要被垃圾回收。如果程序发现某个虚引用已经被加入到引用队列，那么就可以在所引用的对象在被垃圾回收之前采取一些行动。</p><p>应用场景：可以用来跟踪对象被垃圾回收器回收的活动，当一个虚引用指向的对象被垃圾回收器回收之前，可以收到一条系统通知。</p>`,25)])])}const k=a(t,[["render",r]]);export{u as __pageData,k as default};
